 case 3:f.Monstey_W(f.next+8,1);f.Monstey_W(f.backend+0x28,f.next);f.Monstey_W(f.backend+0x10,0x2000);f.Monstey_W(f.backend+0x30,0);f.Monstey_Segment(f.backend+0x3A0,f.chunk-0x1000,0x10000,0,8);a=0;d=f.chunk;break;
 case 4:{f.Monstey_SetBackend(0x300);f.Monstey_W(f.backend+0x38,1);const U cell=f.backend+0x258+U{Monstey_Class(0x300)}*8;a=0;d=cell;break;}
